    std::puts("before");
    int result = inner(value);
    return result;
  };
}

package decorator

func Traced(inner func(int) int) func(int) int {
	return func(value int) int {
		println("before")
		result := inner(value)
		println("after")
		return result
	}
}

pub fn traced<F: Fn(i32) -> i32>(inner: F) -> impl Fn(i32) -> i32 {
    move |value: i32| {
        println!("before");
        let result = inner(value);
        println!("after");
        result
    }
}

