class RealSubject:
    def request(self):
        return 1

class Proxy:
    def __init__(self):
        self.subject = None
    def request(self):
        if self.subject is None:
            self.subject = RealSubject()
        return self.subject.request()

class RealSubject {
  request() { return 1; }
}
class Proxy {
  constructor() { this.subject = null; }
  request() {
    if (this.subject === null) { this.subject = new RealSubject(); }
    return this.subject.request();
  }
}

class RealSubject {
